/**
 * Resolve the backend's Stellar network from the environment against the
 * canonical table (issue #118).
 *
 * environments.toml is the single source of truth (see networks.generated.ts,
 * generated by scripts/network_config.py). Environment variables may still
 * override an endpoint (a private RPC node, say), but never in a way that mixes
 * two networks' identities: pointing STELLAR_NETWORK=mainnet at the testnet RPC,
 * or using a contract id that belongs to another network, fails at startup.
 */
import {
  NETWORKS,
  NETWORK_NAMES,
  networkConfig,
  type NetworkName,
} from "./networks.generated.js";

export interface ResolvedNetwork {
  network: NetworkName;
  networkPassphrase: string;
  rpcUrl: string;
  /** True when STELLAR_RPC_URL overrides the canonical endpoint. */
  rpcUrlOverridden: boolean;
  contracts: { escrow: string | null; oracle: string | null };
}

export class NetworkConfigError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "NetworkConfigError";
  }
}

const PLACEHOLDER = /^(|YOUR_[A-Z0-9_]+_HERE)$/;

function setValue(raw: string | undefined): string | null {
  return raw === undefined || PLACEHOLDER.test(raw.trim()) ? null : raw.trim();
}

/** The other network whose canonical `field` equals `value`, if any. */
function ownedByOther(
  name: NetworkName,
  value: string,
  pick: (n: NetworkName) => string | null,
): NetworkName | null {
  for (const other of NETWORK_NAMES) {
    if (other !== name && pick(other) === value) return other;
  }
  return null;
}

export function resolveNetworkConfig(
  env: NodeJS.ProcessEnv = process.env,
): ResolvedNetwork {
  const name = (env.STELLAR_NETWORK ?? "testnet").trim();
  let canonical;
  try {
    canonical = networkConfig(name);
  } catch (err) {
    throw new NetworkConfigError((err as Error).message);
  }
  const network = canonical.network as NetworkName;

  const passphrase = setValue(env.STELLAR_NETWORK_PASSPHRASE);
  if (passphrase && passphrase !== canonical.networkPassphrase) {
    throw new NetworkConfigError(
      `STELLAR_NETWORK_PASSPHRASE does not belong to ${network} (expected "${canonical.networkPassphrase}")`,
    );
  }

  const rpcOverride = setValue(env.STELLAR_RPC_URL);
  if (rpcOverride) {
    const other = ownedByOther(network, rpcOverride, (n) => NETWORKS[n].rpcUrl);
    if (other) {
      throw new NetworkConfigError(
        `STELLAR_NETWORK=${network} but STELLAR_RPC_URL is ${other}'s RPC endpoint (${rpcOverride}); refusing to mix networks`,
      );
    }
  }

  const contracts = {
    escrow: null as string | null,
    oracle: null as string | null,
  };
  for (const [key, envName] of [
    ["escrow", "CONTRACT_ESCROW"],
    ["oracle", "CONTRACT_ORACLE"],
  ] as const) {
    const value = setValue(env[envName]);
    const expected = canonical.contracts[key];
    if (value) {
      const other = ownedByOther(
        network,
        value,
        (n) => NETWORKS[n].contracts[key],
      );
      if (other) {
        throw new NetworkConfigError(
          `${envName} is the ${other} ${key} contract; STELLAR_NETWORK is ${network}`,
        );
      }
      if (expected && value !== expected) {
        throw new NetworkConfigError(
          `${envName}=${value} disagrees with environments.toml [${network}.contracts].${key} (${expected})`,
        );
      }
    }
    contracts[key] = value ?? expected ?? null;
  }

  return {
    network,
    networkPassphrase: canonical.networkPassphrase,
    rpcUrl: rpcOverride ?? canonical.rpcUrl,
    rpcUrlOverridden: rpcOverride !== null,
    contracts,
  };
}
